struct virtio_gpu_object_array * virtio_gpu_array_from_handles ( struct drm_file * drm_file , u32 * handles , u32 nents ) { struct virtio_gpu_object_array * objs ; u32 i ; objs = virtio_gpu_array_alloc ( nents ) ; if ( ! objs ) { return in ; } for ( i = 0 ; i < nents ; i ++ ) { objs -> objs [ i ] = drm_gem_object_lookup ( drm_file , handles [ i ] ) ; if ( ! objs -> objs [ i ] ) { objs -> nents = i ; virtio_gpu_array_put_free ( objs ) ; return NULL ; } } objs -> nents = i ; return objs ; } 